-- Help page (nav item + Getting Started guide)
('nav.help',                  'en', 'Help'),
('nav.help',                  'et', 'Abi'),
('help.hero_title',           'en', 'The fastest way to get help'),
('help.hero_title',           'et', 'Kiireim viis abi saada'),
('help.hero_sub',             'en', 'Ask Anne directly — she knows exactly how KnoBitz works and can help right away. Her chat window is in the bottom right.'),
('help.hero_sub',             'et', 'Küsi otse Anne käest — ta teab täpselt, kuidas KnoBitz töötab, ja aitab sind kohe. Tema vestlusaken on paremal all.'),
('help.reading_note',         'en', 'Prefer to read it yourself instead? Here\'s a written guide.'),
('help.reading_note',         'et', 'Eelistad pigem ise lugeda? Siin on kirjalik juhend.'),
('help.map_title',            'en', 'The map'),
('help.map_title',            'et', 'Kaart'),
('help.map_body',             'en', 'You\'ll see an interactive knowledge map with five levels — from broad domains (L1) down to individual concepts (L5). Drag and zoom the map, search for concepts in the top search box, and use the filters (e.g. grade band, subject) and layers on the left to make the map clearer.'),
('help.map_body',             'et', 'Näed interaktiivset teadmiste kaarti viie tasemega — laiadest valdkondadest (L1) kuni üksikute mõisteteni (L5). Kaarti saab lohistada ja suumida. Mõisteid saab otsida ülal otsingukastist. Vasakul asuvad filtrid (nt põhikool, gümnaasium, aine) ja kihid, mis aitavad kaarti selgemaks muuta.'),
('help.node_title',           'en', 'Clicking a concept'),
('help.node_title',           'et', 'Mõistel klikkimine'),
('help.node_body',            'en', 'Clicking a concept opens a side panel. Which buttons you see depends on its level:'),
('help.node_body',            'et', 'Kui klikid mõistel, avaneb külgpaneel. Nupud, mida näed, sõltuvad mõiste tasemest:'),
('help.node_l1',              'en', 'L1 (domain): no buttons — pick a subtopic.'),
('help.node_l1',              'et', 'L1 (valdkond): nuppe pole — vali mõni alamteema.'),
('help.node_l2',              'en', 'L2: "Learn this" shows a recommended learning order for its subtopics, with a "Sounds good" button that jumps to the first recommended one.'),
('help.node_l2',              'et', 'L2: „Õpin seda" näitab soovitatud õpijärjekorda alamteemadest, koos nupuga „Sobib", mis viib esimese soovitatud teema juurde.'),
('help.node_l34',             'en', 'L3 and L4: "Set as goal" adds the topic to your goals. "Learn this" opens a structured learning path that walks step by step down to individual lessons.'),
('help.node_l34',             'et', 'L3 ja L4: „Sea eesmärgiks" lisab teema sinu eesmärkide hulka. „Õpin seda" avab struktureeritud õpiraja, mis viib samm-sammult üksikute õppetundideni.'),
('help.node_l45',             'en', 'L4 and L5: "Test me" starts a short 4-question diagnostic test.'),
('help.node_l45',             'et', 'L4 ja L5: „Teen testi" käivitab lühikese 4-küsimuselise diagnostilise testi.'),
('help.node_l5',              'en', 'L5 (individual concept): "Learn this" opens the lesson. The "I know this" toggle lets you mark that you already know it.'),
('help.node_l5',              'et', 'L5 (üksikmõiste): „Õpin seda" avab õppetunni. „Tean seda" lüliti lubab sul ise märkida, et oskad seda juba.'),
('help.lesson_title',         'en', 'The lesson'),
('help.lesson_title',         'et', 'Õppetund'),
('help.lesson_body',          'en', 'Every lesson has four parts: explanation, example, practice, and meaning (why it matters). At any point you can say "too simple" or "too complex," ask for a different explanation, or ask questions directly inside the lesson via the ask bar.'),
('help.lesson_body',          'et', 'Iga õppetund koosneb neljast osast: selgitus, näide, harjutus ja tähendus (miks see oluline on). Igal hetkel saad öelda „liiga lihtne" või „liiga keeruline", paluda teistsugust selgitust, või küsida küsimusi otse tunni sees, küsimuste riba kaudu.'),
('help.test_title',           'en', 'Testing'),
('help.test_title',           'et', 'Testimine'),
('help.test_body',            'en', 'The "Test me" button starts a 4-question adaptive diagnostic test that adjusts to your answers and gives you a read on how well you know the topic.'),
('help.test_body',            'et', '„Teen testi" nupp käivitab 4-küsimuselise adaptiivse diagnostilise testi, mis kohandub sinu vastuste järgi ja annab lõpuks hinnangu, kui hästi seda teemat oskad.'),
('help.goals_title',          'en', 'Goals and your Learner Passport'),
('help.goals_title',          'et', 'Eesmärgid ja Õppijapass'),
('help.goals_body',           'en', 'Goals, progress, achievements, points ("lumens"), and rank are all on your Learner Passport — open it from the menu (☰ icon, top right) under "Account." From there you can also link your account to a teacher or parent with an invite code so they can see your progress.'),
('help.goals_body',           'et', 'Eesmärgid, edenemine, saavutused, luumenid ja järgud on koos näha Õppijapassis — see avaneb menüüst (☰ ikoon üleval paremal) valikust „Konto". Sealt saad ka ühendada oma konto õpetaja või lapsevanemaga ühenduskoodi abil, et nemad näeksid sinu edenemist.'),
('help.notif_settings_title', 'en', 'Notifications and settings'),
('help.notif_settings_title', 'et', 'Teavitused ja seaded'),
('help.notif_settings_body',  'en', 'The same menu has Notifications (reminders and achievements) and Settings (font size, language, colour palette, focus timer, ambient sound).'),
('help.notif_settings_body',  'et', 'Sama menüü alt leiad ka Teavitused (meeldetuletused ja saavutused) ning Seaded (fondisuurus, keel, värvipalett, fookustaimer, taustaheli).')

ON DUPLICATE KEY UPDATE value = VALUES(value);
